  [
    {
      "fieldName": "ucinn_ascendv2__Dynamic_Lookup_to_Configure__c",
      "toolTip": "Enable configurations for defined dynamic lookup. String of object API name and field API name separated by hyphen. Exmaple:\"ucinn_ascendv2__Contact_Report__c-ucinn_ascendv2__Contact__c\".",
      "customFieldParams": {
        "label": "Dynamic Lookup to Configure",
        "type": "text"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Display_Icon__c",
      "toolTip": "For displaying an icon on the lookup.",
      "customFieldParams": {
        "label": "Display Icon",
        "type": "checkbox"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Icon_Name__c",
      "toolTip": "For specifying an Icon Name.",
      "customFieldParams": {
        "label": "Icon Name",
        "type": "text"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Utility_Lookup_Default_Setting__c",
      "disabled": true,
      "toolTip": "The default setting that holds the default values.",
      "customFieldParams": {
        "label": "Utility Lookup Default Setting (Managed)",
        "type": "text"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Fields_To_Display__c",
      "toolTip": "Fields to display on the lookup.",
      "jsonFieldParams": {
        "label": "Fields To Display",
        "type": "listNotJSON",
        "listNotJSONSeperator": ",",
        "valueCustomFieldParams": {
          "type": "text"
        }
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Search_By_Fields__c",
      "toolTip": "For enabling the barcode scanner.",
      "customFieldParams": {
        "type": "picklist",
        "customPicklistValuesString": [
          "ALL FIELDS",
          "NAME FIELDS",
          "EMAIL FIELDS",
          "PHONE FIELDS",
          "SIDEBAR FIELDS"
        ],
        "label": "Search By Fields"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Is_ID_Field_Numeric__c",
      "toolTip": "Only search by ID field when user types in numeric characters.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Is ID Field Numeric"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Where_Clause_Condition_String__c",
      "toolTip": "In the form of \"{0} = 'Business_Organization' OR {1} = 'Corporations_and_Organizations\", where {0} is the first field in the \"Where Clause Fields\" field.{BLANK} prevents inheriting default value.{v.recordId} is contact/account's donor Id.",
      "customFieldParams": {
        "type": "textarea",
        "label": "Where Clause Condition String"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Where_Clause_Fields__c",
      "toolTip": "Fields to query in the where clause. {BLANK} prevents inheriting default setting value.",
      "customFieldParams": {
        "type": "textarea",
        "label": "Where Clause Fields"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__ID_Field_Search_Key_Length__c",
      "toolTip": "Only start to search for the ID field when the search key is this length or more.",
      "customFieldParams": {
        "type": "number",
        "label": "ID Field Search Key Length"
      }
