        "label": "Order By Field API Name",
        "type": "text"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Sort__c",
      "toolTip": "The value can either by ASC or DESC. This field is used to sort Gift Appeals and Proposals",
      "customFieldParams": {
        "label": "Order By ASC or DESC",
        "type": "picklist",
        "customPicklistValues": [
          {
            "label": "--None--",
            "value": ""
          },
          {
            "label": "ASC",
            "value": "ASC"
          },
          {
            "label": "DESC",
            "value": "DESC"
          }
        ]
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Sort_By_Campaign_Member__c",
