  [
    {
      "fieldName": "ucinn_ascendv2__Additional_Fields_To_Query__c",
      "toolTip": "A comma separated list in form [\"field1\",\"field2\"...] which determine what fields to query for. Include namespaces if the field is part of a managed package.",
      "jsonFieldParams": {
        "label": "Additional Fields To Query",
        "helpText": "Add a unique field API name per row.",
        "type": "list",
        "listType": "value",
        "valueCustomFieldParams": {
          "type": "text"
        }
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Fields_to_Diplay_on_Table__c",
      "toolTip": "A comma separated list in form [\"field1\",\"field2\"...] which determine what fields to put onto the table. Include namespaces if the field is part of a managed package.",
      "jsonFieldParams": {
        "label": "Fields to Display on Table",
        "type": "list",
        "listType": "value",
        "valueCustomFieldParams": {
          "type": "text"
        }
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Field_Type_Dict__c",
      "toolTip": "A map in the form {\"field1\":\"type1\",\"field2\":\"type2\"...} which relates the fields defined in the Fields To Display, and how they should appear on the table.",
      "jsonFieldParams": {
        "label": "Field Type Dict",
        "type": "object",
        "helpText": "Configuration to determine how we should show the fields to display.",
        "jsonKeysToValueList": [
          {
            "key": "[CUSTOM]",
            "valueCustomFieldParams": {
              "type": "picklist",
              "customPicklistValuesString": [
                "Id",
                "REFERENCE",
                "REFERENCE-URL",
                "REFERENCE-READONLY",
                "READONLY",
                "EMAIL",
                "PHONE",
                "DATE",
                "DATETIME",
                "INTEGER",
                "DOUBLE",
                "BOOLEAN",
                "STRING",
                "URL",
                "CURRENCY",
                "CURRENCY-READONLY",
                "DATE-READONLY",
                "DATETIME-READONLY",
                "NUMBER-READONLY",
                "PERCENTAGE-READONLY",
                "PHONE-READONLY",
                "RICHTEXT-READONLY",
                "URL-READONLY",
                "TEXTAREA-READONLY",
                "BOOLEAN-READONLY",
                "UNESCAPED-HTML",
                "Compound-Address",
                "ADDRESS-READONLY",
                "PICKLIST-READONLY",
                "MULTIPICKLIST-READONLY",
                "TIME-READONLY",
                "GEOLOCATION-READONLY",
                "ENCRYPTED-READONLY"
              ]
            }
          }
        ]
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Modal_Header__c",
      "toolTip": "Option to set a custom header for the modal.",
      "customFieldParams": {
        "label": "Modal Header",
        "type": "text"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Headers__c",
      "toolTip": "A list in the form [\"header1\", \"header2\"...]defining the headers for the table. If blank, will use the field labels as headers. Make sure to have an equal number of headers as you have fields to display.",
      "jsonFieldParams": {
        "label": "Table Column Headings",
        "type": "list",
        "listType": "value",
        "allowReorder": true,
        "helpText": "Header Labels that correspond to the Fields to Display. If nothing populated it will just use the field labels defined on the fields.",
        "valueCustomFieldParams": {
          "type": "text"
        }
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Enable_Search_Bar__c",
