    },
    {
      "fieldName": "ucinn_ascendv2__Order_by_Direction__c",
      "toolTip": "The value can either by ASC or DESC.",
      "customFieldParams": {
        "label": "Order By ASC or DESC",
        "type": "picklist",
        "customPicklistValues": [
          {
            "label": "--None--",
            "value": ""
          },
          {
            "label": "ASC",
            "value": "ASC"
          },
          {
            "label": "DESC",
            "value": "DESC"
          }
        ]
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Number_of_Records_Per_Load__c",
      "toolTip": "Number of records to load for the table.",
      "customFieldParams": {
        "label": "Number of Records Per Load",
        "type": "number"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Number_of_Records_Per_Page__c",
      "toolTip": "Number of records per page for the search modal table.",
      "customFieldParams": {
        "label": "Number of Records Per Page",
        "type": "number"
      }
    }
  ],
  [
    {
      "fieldName": "BLANK_CREATE_NEW",
      "customFieldParams": {
        "type": "blank"
      }
    }
  ],
  [
    {
      "fieldName": "CREATE_NEW_RECORDS_SETTING",
      "customFieldParams": {
        "type": "header",
        "label": "Create New Record Settings"
      }
    }
