      "fieldName": "ucinn_ascendv2__Enable_Create_New_Record__c",
      "toolTip": "Displays the option to create a new record in the lookup drop down.",
      "customFieldParams": {
        "label": "Enable Create New Record",
        "type": "checkbox"
      }
