  [
    {
      "fieldName": "ucinn_ascendv2__Record_Type_Label__c",
      "toolTip": "Label of the object's record type.",
      "customFieldParams": {
        "label": "Record Type Label",
        "type": "text"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Record_Type_Name__c",
      "toolTip": "API name of the record type.",
      "customFieldParams": {
        "label": "Record Type Name",
        "type": "text"
      }
